#!/usr/bin/env bash
# Regenerate SYMBOLS.md and fail if the Rust .so is missing any C symbol.
set -euo pipefail
cd "$(dirname "$0")"
ROOT="$(cd .. && pwd)"
C_SO="$ROOT/c_src/build/libmujs.so"
R_SO="$ROOT/translation/target/release/libmujs.so"

nm -D --defined-only "$C_SO" | awk '{print $3}' | sort -u > /tmp/mujs_c_syms.txt
nm -D --defined-only "$R_SO" | awk '{print $3}' | sort -u > /tmp/mujs_r_syms.txt
NC=$(wc -l < /tmp/mujs_c_syms.txt)
NR=$(wc -l < /tmp/mujs_r_syms.txt)
MISSING=$(comm -23 /tmp/mujs_c_syms.txt /tmp/mujs_r_syms.txt || true)
EXTRA=$(comm -13 /tmp/mujs_c_syms.txt /tmp/mujs_r_syms.txt || true)
NMISS=$(printf '%s' "$MISSING" | grep -c . || true)
NEXTRA=$(printf '%s' "$EXTRA" | grep -c . || true)
UNDEF=$(nm -D --undefined-only "$R_SO" | awk '{print $2}' | sed 's/@.*//' | sort -u | grep -E '^(js|jsB|jsC|jsP|jsR|jsS|jsU|jsV|jsY)' || true)
NUNDEF=$(printf '%s' "$UNDEF" | grep -c . || true)

{
echo "# SYMBOLS.md — exported-symbol parity (mechanically generated by symcheck.sh)"
echo
echo "\`nm -D --defined-only\` on both shared objects."
echo
echo "- C    \`c_src/build/libmujs.so\`: **$NC** exported symbols"
echo "- Rust \`translation/target/release/libmujs.so\`: **$NR** exported symbols"
echo "- Missing from Rust: **$NMISS**"
echo "- Extra in Rust: **$NEXTRA**"
echo "- Undefined (unresolved) mujs symbols in the Rust \`.so\`: **$NUNDEF**"
echo
if [ "$NMISS" != "0" ]; then
  echo "## MISSING FROM RUST"
  echo
  printf '%s\n' "$MISSING" | sed 's/^/- `/; s/$/`/'
  echo
fi
if [ "$NEXTRA" != "0" ]; then
  echo "## EXTRA IN RUST"
  echo
  printf '%s\n' "$EXTRA" | sed 's/^/- `/; s/$/`/'
  echo
fi
echo "Every remaining undefined symbol in the Rust \`.so\` belongs to libc or the"
echo "libgcc unwinder:"
echo
echo '```'
nm -D --undefined-only "$R_SO" | awk '{print $2}' | sed 's/@.*//' | sort -u \
  | grep -vE '^(js|jsB|jsC|jsP|jsR|jsS|jsU|jsV|jsY)' | tr '\n' ' ' | fold -s -w 96
echo
echo '```'
echo
echo "## Parity table"
echo
echo "| # | symbol | in C .so | in Rust .so |"
echo "|---|--------|----------|-------------|"
i=0
while read -r s; do
  i=$((i+1))
  if grep -qxF "$s" /tmp/mujs_r_syms.txt; then r="yes"; else r="**MISSING**"; fi
  echo "| $i | \`$s\` | yes | $r |"
done < /tmp/mujs_c_syms.txt
} > SYMBOLS.md

echo "SYMBOLS.md: C=$NC RUST=$NR missing=$NMISS extra=$NEXTRA undefined-mujs=$NUNDEF"
if [ "$NMISS" != "0" ] || [ "$NUNDEF" != "0" ]; then
  echo "SYMBOL PARITY FAILED" >&2
  exit 1
fi
